{"file_path":"/home/huythong/.hybridagent/workspaces/default/paw/core/executor.py","content":""""
PAW Core — Executor Base Protocol and Mock Executor

All executors implement the Executor protocol. MockExecutor enables
E2E testing without real LLM calls.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass
from datetime import datetime
from typing import Any

from .models import Capability, ID, Result
from .ledger import (
    log_execution_started,
    log_execution_completed,
    log_tool_called,
)
from .task import Task
from .storage import db


@dataclass
class ExecutorResult:
    """Standardized result from any executor."""
    success: bool
    output: Any = None
    error: str | None = None
    artifacts: list[dict] = None  # type: ignore
    metadata: dict[str, Any] = None  # type: ignore

    def __post_init__(self):
        if self.artifacts is None:
            self.artifacts = []
        if self.metadata is None:
            self.metadata = {}


class Executor(ABC):
    """Base protocol for all executors."""

    name: str = "base"
    capabilities: list[Capability] = []

    @abstractmethod
    async def execute(self, task: Task, context: str) -> ExecutorResult:
        """Execute the task with given context. Return structured result."""
        ...

    async def can_handle(self, task: Task) -> bool:
        """Check if this executor can handle the task's capabilities."""
        if not self.capabilities:
            return True  # No restriction
        task_caps = set(task.requested_capabilities)
        executor_caps = set(self.capabilities)
        return task_caps.issubset(executor_caps)


class MockExecutor(Executor):
    """Mock executor for testing. Returns deterministic responses."""

    name = "mock"
    capabilities = [
        Capability.FILESYSTEM_READ,
        Capability.FILESYSTEM_WRITE,
        Capability.SHELL_EXECUTE,
    ]

    def __init__(self, predefined_responses: dict[str, ExecutorResult] | None = None):
        self.predefined_responses = predefined_responses or {}
        self.call_log: list[dict] = []

    async def execute(self, task: Task, context: str) -> ExecutorResult:
        await log_execution_started(task.id, self.name)

        # Log the execution
        self.call_log.append({
            "task_id": task.id,
            "goal": task.goal,
            "context_length": len(context),
            "timestamp": datetime.utcnow().isoformat(),
        })

        # Check for predefined response
        if task.id in self.predefined_responses:
            result = self.predefined_responses[task.id]
            await log_execution_completed(task.id, True, result.output, result.error)
            return result

        # Default: return a mock success based on goal keywords
        output = self._generate_mock_output(task.goal)

        await log_tool_called(task.id, "mock.execute", {"goal": task.goal}, output)
        await log_execution_completed(task.id, True, output, None)

        return ExecutorResult(success=True, output=output, metadata={"mock": True})

    def _generate_mock_output(self, goal: str) -> str:
        """Generate a deterministic mock output based on goal."""
        goal_lower = goal.lower()

        if "hello" in goal_lower or "chào" in goal_lower:
            return "Xin chào! Đây là mock response từ MockExecutor."
        elif "tính" in goal_lower or "calculate" in goal_lower:
            return "Kết quả tính toán: 42"
        elif "tóm tắt" in goal_lower or "summary" in goal_lower or "summarize" in goal_lower:
            return "Tóm tắt: Đây là nội dung được tóm tắt bởi MockExecutor."
        elif "tìm" in goal_lower or "search" in goal_lower or "search" in goal_lower:
            return "Kết quả tìm kiếm: [Mock] 3 kết quả liên quan được tìm thấy."
        elif "viết" in goal_lower or "write" in goal_lower or "code" in goal_lower:
            return "# Mock Code\nprint('Hello from MockExecutor')"
        elif "phân tích" in goal_lower or "analyze" in goal_lower:
            return "Phân tích: MockExecutor đã phân tích và đưa ra kết luận mẫu."
        elif "lập kế hoạch" in goal_lower or "plan" in goal_lower:
            return "Kế hoạch:\n1. Bước 1\n2. Bước 2\n3. Bước 3"
        else:
            return f"MockExecutor đã xử lý: {goal[:100]}..."

    def get_call_log(self) -> list[dict]:
        return self.call_log


class ExecutorRegistry:
    """Registry of available executors."""

    def __init__(self):
        self._executors: dict[str, Executor] = {}

    def register(self, executor: Executor) -> None:
        self._executors[executor.name] = executor

    def get(self, name: str) -> Executor | None:
        return self._executors.get(name)

    def list(self) -> list[Executor]:
        return list(self._executors.values())

    def find_for_task(self, task: Task) -> list[Executor]:
        """Find all executors that can handle the task."""
        return [e for e in self._executors.values() if e.can_handle(task)]


# Global registry
executor_registry = ExecutorRegistry()

# Register mock by default
executor_registry.register(MockExecutor())"}

